import axios from 'axios';
import type { Session, Driver, Track, Monopost, MqttAuth, Timestamp } from '@telemetry/shared';

const API_URL = import.meta.env.VITE_API_URL;

export const api = {



  // --- FILE ---
  uploadFile: async (file: File) => {
    
    const formData = new FormData();
    formData.append('file', file);
    
    const response = await axios.post<{ fileName: string }>(
      `${API_URL}/upload`, 
      formData,
      { headers: { 'Content-Type': 'multipart/form-data' } }
    );
    return response.data.fileName; // Returns the unique filename generated by backend
  },

  downloadFile: async (fileName: string) => {
    const response = await axios.get(`${API_URL}/download/${fileName}`, {
      responseType: 'blob', // Important: tells axios to handle binary data
    });
    return response.data; // Returns a Blob (file-like object)
  },
    fetchJsonFile: async (fileName: string) => {
    const response = await axios.get(`${API_URL}/download/${fileName}`, {
      responseType: 'json', // Axios automatically parses the JSON
    });
    return response.data;
  },


  // --- SESSIONS ---
  saveSession: async (sessionData: Session) => {
   
    const response = await axios.post<{ success: boolean; id: number }>(
      `${API_URL}/sessions`, 
      sessionData
    );
    return response.data;
  },

  getSessions: async () => {
    const response = await axios.get<Session[]>(`${API_URL}/sessions`);
    return response.data;
  },
   getSessionById: async(sessionId: number)=>{
    const response = await axios.get<Session>(`${API_URL}/sessions/${sessionId}`,);
    return response.data;
  },


// --- TRACKS ---
  getTrackById: async(trackId: number)=>{
    const response = await axios.get<Track>(`${API_URL}/tracks/${trackId}`,);
    return response.data;
  },
  getTracks: async () => {
    const response = await axios.get<Track[]>(`${API_URL}/tracks`);
    return response.data;
  },
  saveTrack: async (trackData: Track) => {
    const response = await axios.post(`${API_URL}/tracks`, trackData);
    return response.data;
  },
  

// --- TIMESTAMPS ---
  saveTimestamp: async (timestampData: Timestamp) => {
    const response = await axios.post(`${API_URL}/timestamps`, timestampData);
    return response.data;
  },
  getTimestamps: async (column: string, value: string | number) => {
    const response = await axios.get(`${API_URL}/timestamps/filters`, {
      // Axios automatically serializes these into ?column=...&value=...
      params: {
        column: column,
        value: value
      }
    });
    return response.data;
  },


// --- MONOSPOSTS ---
  saveMonoposts: async (monopostData: Monopost) => {
    const response = await axios.post(`${API_URL}/monoposts`, monopostData);
    return response.data;
  },

  getMonoposts: async()=>{
    const response = await axios.get<Monopost[]>(`${API_URL}/monoposts`,);
    return response.data;
  },

  deleteMonopost: async(monopostId: number)=>{
    const response = await axios.delete(`${API_URL}/monoposts/${monopostId}`,);
    return response.data;
  },


// --- DRIVERS ---  
  saveDriver: async (driverData: Driver) => {
    
    const response = await axios.post(`${API_URL}/drivers`, driverData);
    return response.data;
  },
  getDrivers: async()=>{
    const response = await axios.get<Driver[]>(`${API_URL}/drivers`,);
    return response.data;
  },
  getDriverById: async(driverId: number)=>{
    const response = await axios.get<Driver>(`${API_URL}/drivers/${driverId}`,);
    return response.data;
  },
};